  "currentTexts": {
    "keyName": {
      "sourceKey": "Spell_BriarW_Name",
      "text": "血莽 / 噬击"
    },
    "keyTooltip": {
      "sourceKey": "Spell_BriarW_Tooltip",
      "text": "贝蕾亚跳跃并进入一种<keywordMajor>血莽</keywordMajor>状态，自我嘲讽至相距最近的那个敌人，持续@BerserkDuration@秒，优先以英雄为目标。在<keywordMajor>血莽</keywordMajor>状态下，她获得<attackSpeed>@BerserkAS*100@%攻击速度</attackSpeed>和<speed>@BerserkMS*100@%移动速度</speed>，并且她的攻击会对目标四周的敌人们造成<physicalDamage>@TotalAoEDamage@物理伤害</physicalDamage>。<br><br>贝蕾亚可以<recast>再次施放</recast>这个技能来强化她的下一次攻击。这次攻击造成<physicalDamage>@TotalAttackBonusDamage@ + @TotalAttackPercentMissingHealth@%已损失生命值的物理伤害</physicalDamage>并<healing>为贝蕾亚提供@AttackMaxHPHeal@+@AttackHealPercent*100@%已造成伤害值的治疗效果</healing>。<br>"
    },
    "keyCost": {
      "sourceKey": "Spell_BriarP_Cost",
      "text": "消耗<font color='#CC3300'>@Spell.BriarP:CurrentHealthPercentCost*100@%当前生命值</font>"
    },
    "keyTooltipExtendedBelowLine": {
      "sourceKey": "Spell_BriarW_TooltipExtendedBelowLine",
      "text": "<rules>噬咬会对小兵和野怪造成@MonsterAndMinionPercentMod*100@%提升伤害(至多为@MaxMonsterDamage@已损失生命值伤害)。<br>这个技能不会移除或替代<spellName>{{Spell_BriarR_Name}}</spellName>的强化版<keywordMajor>血莽</keywordMajor>。</rules>"
    },
    "keySummary": {
      "sourceKey": "Spell_BriarW_Summary",
      "text": "贝蕾亚向前跳跃并击碎她的囚枷，进入一种【血莽】状态来使她无休止地追击相距最近的那个敌人（优先以英雄为目标）。在【血莽】状态下，她的攻击速度和移动速度获得提升，并且她的攻击会在她目标四周的一个区域内造成伤害。<br><br>贝蕾亚可以在【血莽】状态下再次激活这个技能，来让她的下一次攻击噬咬她的目标，造成基于目标已损失生命值的额外伤害，并且基于她造成的伤害来为她提供治疗效果。"
    }
  }
